IP_NAME = "Ethernet"

def generate():
    ist = datetime.timezone(datetime.timedelta(hours=5, minutes=30))
    now_ist = datetime.datetime.now(ist)
    timestamp = now_ist.strftime('%Y%m%d_%H%M%S')
    filename = f"{IP_NAME}_TestPlan_{timestamp}.xlsx"

    tp_names = {r["Test Case Name"] for r in TESTPLAN_JSON}
    meta_names = {r["Test Case Name"] for r in META_JSON}
    for name in tp_names:
        if name not in meta_names:
            return None, "FAILED", None

    wb = Workbook()
    header_font = Font(bold=True, color="FFFFFF", size=11)
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    wrap_alignment = Alignment(wrap_text=True, vertical="top")
    thin_border = Border(left=Side(style='thin'), right=Side(style='thin'), top=Side(style='thin'), bottom=Side(style='thin'))

    tp_columns = ["Index","SS / Module","Feature","Test Case Name","Speed","Mode","Memory Start Offset","Memory End Offset","Test Description","Test Steps / Procedure","Impacted Registers","Validation / Acceptance Criteria","Remarks","Code Generation (Required / Not)"]

    ws_tp = wb.active
    ws_tp.title = "TestPlan"
    for col_idx, col_name in enumerate(tp_columns, 1):
        cell = ws_tp.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = wrap_alignment
        cell.border = thin_border

    for row_idx, record in enumerate(TESTPLAN_JSON, 2):
        for col_idx, col_name in enumerate(tp_columns, 1):
            if col_name == "Code Generation (Required / Not)":
                cell = ws_tp.cell(row=row_idx, column=col_idx, value="")
            else:
                cell = ws_tp.cell(row=row_idx, column=col_idx, value=record.get(col_name, ""))
            cell.alignment = wrap_alignment
            cell.border = thin_border

    code_gen_col = len(tp_columns)
    dv = DataValidation(type="list", formula1='"Required,Not Required"', allow_blank=True, showDropDown=False)
    dv.error = "Please select Required or Not Required"
    dv.errorTitle = "Invalid Entry"
    dv.prompt = "Select Code Generation status"
    dv.promptTitle = "Code Generation"
    col_letter = get_column_letter(code_gen_col)
    last_row = len(TESTPLAN_JSON) + 1
    dv.sqref = f"{col_letter}2:{col_letter}{last_row}"
    ws_tp.add_data_validation(dv)

    for col_idx in range(1, len(tp_columns) + 1):
        max_len = 0
        for row in ws_tp.iter_rows(min_col=col_idx, max_col=col_idx, min_row=1, max_row=last_row):
            for cell in row:
                if cell.value:
                    for line in str(cell.value).split('\n'):
                        max_len = max(max_len, len(line))
        ws_tp.column_dimensions[get_column_letter(col_idx)].width = max(min(max_len + 4, 80), 15)

    ws_tp.freeze_panes = "A2"

    meta_columns = ["Test Case Name","Meta Headers","Meta Macros","Meta Arrays","Meta Types","Meta Function Inventory","Meta Test Description","Meta Test Steps / Procedure","Meta Impacted Registers","Meta Validation / Acceptance Criteria"]

    ws_meta = wb.create_sheet(title="MetaData")
    for col_idx, col_name in enumerate(meta_columns, 1):
        cell = ws_meta.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = wrap_alignment
        cell.border = thin_border

    for row_idx, record in enumerate(META_JSON, 2):
        for col_idx, col_name in enumerate(meta_columns, 1):
            cell = ws_meta.cell(row=row_idx, column=col_idx, value=record.get(col_name, ""))
            cell.alignment = wrap_alignment
            cell.border = thin_border

    meta_last_row = len(META_JSON) + 1
    for col_idx in range(1, len(meta_columns) + 1):
        max_len = 0
        for row in ws_meta.iter_rows(min_col=col_idx, max_col=col_idx, min_row=1, max_row=meta_last_row):
            for cell in row:
                if cell.value:
                    for line in str(cell.value).split('\n'):
                        max_len = max(max_len, len(line))
        ws_meta.column_dimensions[get_column_letter(col_idx)].width = max(min(max_len + 4, 80), 15)

    ws_meta.freeze_panes = "A2"
    ws_meta.sheet_state = 'veryHidden'

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    content_b64 = base64.b64encode(buf.read()).decode('ascii')

    wb2 = load_workbook(io.BytesIO(base64.b64decode(content_b64)))
    assert "TestPlan" in wb2.sheetnames
    assert "MetaData" in wb2.sheetnames
    assert wb2["TestPlan"].max_row - 1 == len(TESTPLAN_JSON)
    assert wb2["MetaData"].max_row - 1 == len(META_JSON)
    assert wb2["TestPlan"].cell(row=1, column=code_gen_col).value == "Code Generation (Required / Not)"
    wb2.close()

    return filename, "PASSED", content_b64

if __name__ == "__main__":
    fn, val, b64 = generate()
    if b64:
        with open(fn, 'wb') as f:
            f.write(base64.b64decode(b64))
        print(json.dumps({"status":"SUCCESS","filename":fn,"validation":val,"rows_testplan":len(TESTPLAN_JSON),"rows_metadata":len(META_JSON)}, indent=2))
    else:
        print(json.dumps({"status":"FAILURE","validation":val}, indent=2))
